17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = addressNormalizer.normalize(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        if (!owner.isPostcodeValid()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        if (owner.getRegistrationDate() != null
133	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        LocalDate effectiveDate = owner.getRegistrationDate() != null
137	            ? owner.getRegistrationDate() : LocalDate.now();
138	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
139	        if (isDailyLimitReached(owner.getRegistrationDate())) {
140	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
141	        }
142	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        if (sharesHousehold) {
144	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
145	        }
146	        if (isDuplicate(owner)) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        if (isCityAtCapacity(owner.getCity())) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        assignDerivedAttributes(owner);
153	        this.clinicService.saveOwner(owner);
154	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    /**
163	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
164	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
165	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
166	     * householdSize}. Each is computed from the owner's own fields together with the owners already
167	     * present, so this runs after the owner has been validated and has passed the duplicate and
168	     * capacity checks, and immediately before it is persisted.
169	     */
170	    private void assignDerivedAttributes(Owner owner) {
171	        owner.setCustomerCode(customerCode(owner));
172	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
173	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
174	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
175	    }
176	
177	    /**
178	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
179	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
180	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
181	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
182	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
183	     * every value built from the customer code (the membership number and its check digit) and the
184	     * owner's locality are derived from it.
185	     */
186	    private String customerCode(Owner owner) {
187	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
188	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
189	        return region + "-" + hash8;
190	    }
191	
192	    /**
193	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
194	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
195	     * (business-day) registration date of the owner being created, so owners are counted per
196	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
197	     */
198	    private boolean isDailyLimitReached(LocalDate day) {
199	        long count = this.clinicService.findAllOwners().stream()
200	            .filter(existing -> day.equals(existing.getRegistrationDate()))
201	            .count();
202	        return count >= 100;
203	    }
204	
205	    /**
206	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
207	     * more than 80 owners have already been created for the given business day. Counts the owners
208	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
209	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
210	     * warning.
211	     */
212	    private boolean isBulkSignup(LocalDate day) {
213	        long count = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> day.equals(existing.getRegistrationDate()))
215	            .count();
216	        return count > 80;
217	    }
218	
219	    /**
220	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
221	     * advance it to the following Monday; a weekday is returned unchanged.
222	     */
223	    private LocalDate toBusinessDay(LocalDate date) {
224	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
225	            date = date.plusDays(1);
226	        }
227	        return date;
228	    }
229	
230	    /**
231	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
232	     * more owners. Cities are compared case-insensitively.
233	     */
234	    private boolean isCityAtCapacity(String city) {
235	        long count = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
237	            .count();
238	        return count >= 50;
239	    }
240	
241	    /**
242	     * The number of existing owners that already share the given firstName and lastName,
243	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
244	     * whitespace runs collapsed). Counted over the owners present before this create.
245	     */
246	    private int namesakeCount(String firstName, String lastName) {
247	        String candidateFirstName = normalizeName(firstName);
248	        String candidateLastName = normalizeName(lastName);
249	        return (int) this.clinicService.findAllOwners().stream()
250	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
251	                && normalizeName(existing.getLastName()).equals(candidateLastName))
252	            .count();
253	    }
254	
255	    /**
256	     * The number of members in this owner's household after this create: the count of existing
257	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
258	     * created. An owner with no household ({@code householdId == null}) is a household of one.
259	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
260	     * does not depend on the order in which household members were created.
261	     */
262	    private int householdSize(String householdId) {
263	        if (householdId == null) {
264	            return 1;
265	        }
266	        long existing = this.clinicService.findAllOwners().stream()
267	            .filter(other -> householdId.equals(other.getHouseholdId()))
268	            .count();
269	        return (int) existing + 1;
270	    }
271	
272	    /**
273	     * The number of national (subscriber) digits required for each known country calling
274	     * code, keyed by the code's digits (without the leading '+'). A number whose country
275	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
276	     * requires 9 national digits and '+1' requires 10.
277	     */
278	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
279	        "1", 10,
280	        "61", 9);
281	
282	    /**
283	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
284	     * cannot form a valid E.164 number.
285	     *
286	     * <p>A leading '+' and country code are kept when present; otherwise country code
287	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
288	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
289	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
290	     * exactly the national-digit count that code requires (see
291	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
292	     */
293	    private String toE164(String telephone) {
294	        if (telephone == null) {
295	            return null;
296	        }
297	        boolean hasCountryCode = telephone.trim().startsWith("+");
298	        String digits = telephone.replaceAll("\\D", "");
299	        String e164;
300	        if (hasCountryCode) {
301	            e164 = digits;
302	        } else {
303	            if (digits.startsWith("0")) {
304	                digits = digits.substring(1);
305	            }
306	            e164 = "61" + digits;
307	        }
308	        if (e164.length() < 8 || e164.length() > 15) {
309	            return null;
310	        }
311	        if (!hasValidNationalLength(e164)) {
312	            return null;
313	        }
314	        return "+" + e164;
315	    }
316	
317	    /**
318	     * Whether the E.164 digit string (no leading '+') carries the national-number length
319	     * required by its country calling code. The longest matching known code wins; a number
320	     * whose country code is not recognised passes this check (its length is governed only by
321	     * the general 8-15 digit bound in {@link #toE164}).
322	     */
323	    private boolean hasValidNationalLength(String e164) {
324	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
325	            .filter(entry -> e164.startsWith(entry.getKey()))
326	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
327	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
328	            .orElse(true);
329	    }
330	
331	    /**
332	     * Whether the candidate owner duplicates an owner that already exists, and so must be
333	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
334	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
335	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
336	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
337	     * of the key, two members of the same household with different telephones have different
338	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
339	     */
340	    private boolean isDuplicate(Owner owner) {
341	        String identityKey = owner.getIdentityKey();
342	        return this.clinicService.findAllOwners().stream()
343	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
344	    }
345	
346	    /**
347	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
348	     * to a single space and lower-case. A null value normalizes to the empty string.
349	     */
350	    private String normalizeName(String value) {
351	        if (value == null) {
352	            return "";
353	        }
354	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
355	    }
356	
357	    /**
358	     * A stable shared identifier for the household formed by a given lastName and address.
359	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
360	     * lastName and address, so every owner sharing the same household is assigned the same
361	     * value regardless of the order in which they are created. Formatted as the first 12
362	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
363	     */
364	    private String householdId(String lastName, String address) {
365	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
366	        return shaHexUpper(key).substring(0, 12);
367	    }
368	
369	    /**
370	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
371	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
372	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
373	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
374	     * {@link #customerCode} keeps the first 8).
375	     */
376	    private String shaHexUpper(String input) {
377	        try {
378	            byte[] digest = MessageDigest.getInstance("SHA-256")
379	                .digest(input.getBytes(StandardCharsets.UTF_8));
380	            StringBuilder sb = new StringBuilder(digest.length * 2);
381	            for (byte b : digest) {
382	                sb.append(String.format("%02x", b));
383	            }
384	            return sb.toString().toUpperCase();
385	        }
386	        catch (NoSuchAlgorithmException e) {
387	            throw new IllegalStateException("SHA-256 not available", e);
388	        }
389	    }
390	
391	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
392	    @Override
393	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
394	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
395	        if (currentOwner == null) {
396	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
397	        }
398	        currentOwner.setAddress(ownerFieldsDto.getAddress());
399	        currentOwner.setCity(ownerFieldsDto.getCity());
400	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
401	        currentOwner.setLastName(ownerFieldsDto.getLastName());
402	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
403	        this.clinicService.saveOwner(currentOwner);
404	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
405	    }
406	
407	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
408	    @Transactional
409	    @Override
410	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
411	        Owner owner = this.clinicService.findOwnerById(ownerId);
412	        if (owner == null) {
413	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
414	        }
415	        this.clinicService.deleteOwner(owner);
416	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
417	    }
418	
419	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
420	    @Override
421	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
422	        Owner owner = this.clinicService.findOwnerById(ownerId);
423	        if (owner == null) {
424	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
425	        }
426	        HttpHeaders headers = new HttpHeaders();
427	        Pet pet = petMapper.toPet(petFieldsDto);
428	        owner.setId(ownerId);
429	        pet.setOwner(owner);
430	        pet.getType().setName(null);
431	        this.clinicService.savePet(pet);
432	        PetDto petDto = petMapper.toPetDto(pet);
433	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
434	            .buildAndExpand(pet.getId()).toUri());
435	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
441	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
442	        if (currentOwner != null) {
443	            Pet currentPet = this.clinicService.findPetById(petId);
444	            if (currentPet != null) {
445	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
446	                currentPet.setName(petFieldsDto.getName());
447	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
448	                this.clinicService.savePet(currentPet);
449	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
450	            }
451	        }
452	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
453	    }
454	
455	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
456	    @Override
457	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
458	        HttpHeaders headers = new HttpHeaders();
459	        Visit visit = visitMapper.toVisit(visitFieldsDto);
460	        Pet pet = new Pet();
461	        pet.setId(petId);
462	        visit.setPet(pet);
463	        this.clinicService.saveVisit(visit);
464	        VisitDto visitDto = visitMapper.toVisitDto(visit);
